    ranks=ranks.drop(columns=['campaign_rank','rank_change_vs_publisher']).merge(selected[['campaign_id','campaign_rank','publisher_rank','rank_change_vs_criteo','absolute_rank_change']],on='campaign_id')
    ranks['rank_change_vs_publisher']=ranks.rank_change_vs_criteo
    rankpairs=correlations[(correlations.window_days==30)&(correlations.method_a=='publisher')&(correlations.method_b=='last_click_proxy')]
    countpair=rankpairs[rankpairs.metric=='credited_conversions'].iloc[0]
    rankdisplay=rankpairs.copy();rankdisplay['metric']=rankdisplay.metric.map({'credited_conversions':'Attributed conversions','transformed_cost_per_attributed_conversion':'Transformed CPA','attributed_conversion_share':'Attributed conversion share'})
    movers=ranks.loc[ranks.rank_change_vs_publisher.abs().sort_values(ascending=False).index].head(8)
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.titlesize':13,'axes.labelsize':10,'axes.titleweight':'bold',
        'axes.edgecolor':'#ccdad4','axes.spines.top':False,'axes.spines.right':False,'axes.labelcolor':INK,'text.color':INK,'xtick.color':MUTED,'ytick.color':MUTED,'figure.facecolor':'white','savefig.facecolor':'white'})
    def save(fig,name):
        fig.savefig(figs/f'{name}.png',dpi=160,bbox_inches='tight');plt.close(fig)
    def image(name,alt): return f'<div class="chart-scroll"><img class="chart" src="figures/{name}.png" alt="{html.escape(alt)}" loading="lazy"></div><a class="note" href="figures/{name}.png" target="_blank" rel="noopener">Open full-size chart ↗</a>'
    fig,ax=plt.subplots(1,2,figsize=(12,4.2),layout='constrained')
    names=['publisher','first_click_proxy','last_click_proxy','linear_proxy']
    vals=[windows[(windows.model==n)&(windows.window_days==30)].credited_conversions.iloc[0] for n in names]
    bars=ax[0].barh([LABELS[n] for n in names],vals,color=[ORANGE,TEAL,TEAL,TEAL]);ax[0].invert_yaxis();ax[0].set_xlim(0,max(vals)*1.24)
    for bar,value in zip(bars,vals): ax[0].text(value+5000,bar.get_y()+bar.get_height()/2,f'{value:,.0f}',va='center',fontsize=9)
    ax[0].set(title='Same events. Different credited totals.',xlabel='Credited conversions · 30-day proxies');ax[0].xaxis.set_major_formatter(FuncFormatter(lambda x,_:f'{x/1000:.0f}k'))
    ax[1].plot(last.window_days,last.credited_conversions,'o-',color=TEAL,lw=2);ax[1].axhline(vals[0],color=ORANGE,ls='--',label='Criteo-reported benchmark')
    ax[1].set(title='Longer windows expand eligibility',xlabel='Window in days',ylabel='Credited conversions',xticks=[1,7,14,30],ylim=(0,500000));ax[1].legend(fontsize=8);ax[1].yaxis.set_major_formatter(FuncFormatter(lambda x,_:f'{x/1000:.0f}k'))
    save(fig,'attribution_definitions')
    fig,ax=plt.subplots(1,2,figsize=(12,4.2),layout='constrained')
    ax[0].bar(hist.lag_day,hist.conversions,color=TEAL,width=.85);ax[0].set(title='Conversions have a long lag tail',xlabel='Days since last clicked impression (proxy)',ylabel='Canonical conversions',xlim=(-.7,30));ax[0].yaxis.set_major_formatter(FuncFormatter(lambda x,_:f'{x/1000:.0f}k'))
    labels=[str(int(x)) for x in movers.campaign_id]
    for y,(_,r) in enumerate(movers.iterrows()):
        ax[1].plot([r.campaign_rank,r.publisher_rank],[y,y],color='#bed1c9',lw=3)
    ax[1].scatter(movers.publisher_rank,range(len(movers)),color=ORANGE,label='Criteo-reported');ax[1].scatter(movers.campaign_rank,range(len(movers)),color=TEAL,label='30-day last-click proxy')
    ax[1].set(yticks=range(len(movers)),yticklabels=labels,xlim=(1,ranking['eligible_campaigns']),xlabel='Conversion-count rank · 1 is highest',title='Largest rank changes · volume-qualified cohort');ax[1].invert_yaxis();ax[1].legend(fontsize=8,loc='upper center',bbox_to_anchor=(.5,-.20),ncol=2)
    save(fig,'lags_and_ranks')
    fig,axes=plt.subplots(1,3,figsize=(12,4),layout='constrained')
    methods=['publisher','first_click_proxy','last_click_proxy','linear_proxy']
    for ax,metric,title in zip(axes,['credited_conversions','transformed_cost_per_attributed_conversion','attributed_conversion_share'],['Attributed conversions','Transformed CPA','Attributed conversion share']):
        pairs=correlations[(correlations.window_days==30)&(correlations.metric==metric)]
        matrix=pairs.pivot(index='method_a',columns='method_b',values='spearman_rho').reindex(index=methods,columns=methods).to_numpy()
        ax.imshow(matrix,vmin=-1,vmax=1,cmap='BrBG')
        ax.set(xticks=range(4),yticks=range(4),xticklabels=['Criteo','First','Last','Linear'],yticklabels=['Criteo','First','Last','Linear'],title=title)
        for i in range(4):
            for j in range(4): ax.text(j,i,'N/A' if np.isnan(matrix[i,j]) else f'{matrix[i,j]:.3f}',ha='center',va='center',color='white' if abs(matrix[i,j])>.55 else INK)
    fig.suptitle('Spearman rank correlation · 30-day proxies · fixed volume-qualified campaigns',fontsize=13)
